import React, { Component } from "react";
import axios from "axios";
import "./Service.css";
import { Progress } from 'react-sweet-progress';
import "react-sweet-progress/lib/style.css";

class Service extends Component {
    constructor(props) {
        super(props);
        this.state = {
            servicePage: null,
            contentArray: [],
            loading: false,
            progress: 0,
            error: null,
        };
    }

    componentDidMount() {
        fetch("http://localhost:3001/pages/6", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({}),
        })
            .then((response) => {
                if (!response.ok) {
                    throw new Error(`Network response was not ok: ${response.statusText}`);
                }
                return response.json();
            })
            .then((page) => {
                console.log('Fetched page:', page);
                let contentArray = [];
                try {
                    contentArray = Array.isArray(page.content)
                        ? page.content
                        : JSON.parse(page.content);
                } catch (error) {
                    console.error('Error parsing content:', error);
                }
                console.log('Content array:', contentArray);
                this.setState({ servicePage: page, contentArray });
            })
            .catch((error) => {
                console.error('Fetch error:', error);
                this.setState({ error: "Error fetching data" });
            });
    }

    fetchData = async () => {
        this.setState({
            loading: true,
            progress: 0,
        });

        try {
            const response = await axios.post("http://localhost:3001/trackipetmap", {
                pet_id: 1, // Replace with the correct pet_id
            }, {
                onDownloadProgress: (progressEvent) => {
                    const total = progressEvent.total || 100;
                    const current = progressEvent.loaded;
                    const progress = Math.round((current / total) * 100);
                    console.log("Progress:", progress, "Loaded:", current);
                    this.setState({ progress });
                }
            });

            const { lat, lng } = response.data;
            console.log('Fetched location:', { lat, lng });
            const interval = setInterval(() => {
                this.setState((prevState) => {
                    const newProgress = Math.min(prevState.progress + 10, 100);
                    if (newProgress >= 100) {
                        clearInterval(interval);
                        setTimeout(() => { 
                            window.location.href = `/map?lat=${lat}&lng=${lng}&pet_id=1`; 
                        }, 1000); 
                    }
                    return { progress: newProgress };
                });
            }, 200);
        } catch (error) {
            console.error('Axios error:', error);
            this.setState({ error: "Error fetching location data" });
        } finally {
            this.setState({ loading: false });
        }
    };

    render() {
        const { servicePage, contentArray, loading, progress, error } = this.state;

        if (error) return <div>{error}</div>;
        if (!servicePage) return <div>PAGE NOT FOUND</div>;

        return (
            <div className="container">
                {loading ? (
                    <div>
                        <Progress type="circle" percent={progress} />
                    </div>
                ) : (
                    <div className="content-section">
                        {contentArray.length > 0 ? (
                            <>
                                <p className="Hello">{contentArray[0]?.p || contentArray[0]}</p>
                                <p className="Miss">{contentArray[1]?.p || contentArray[1]}</p>
                            </>
                        ) : (
                            <div>No content available</div>
                        )}

                        <img src="./media/dog1.png" alt="Dog" className="dog-image" />

                        <button className="location" onClick={this.fetchData}>
                            Pet's Location
                        </button>
                    </div>
                )}
            </div>
        );
    }
}

export default Service;
